const $=s=>document.querySelector(s);
const nf=new Intl.NumberFormat('nb-NO');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const kr=n=>nf.format(Math.round(n||0))+' kr';
const mill=n=>(n/1e6).toLocaleString('nb-NO',{minimumFractionDigits:1,maximumFractionDigits:1})+' mill.';
const short=n=>n>=1e6?mill(n):n>=1000?Math.round(n/1000)+' k':nf.format(Math.round(n));
const pct=x=>Math.round(x*100)+' %';
const uid=p=>p+'-'+Math.random().toString(36).slice(2,8)+Date.now().toString(36).slice(-4);
const today=()=>{const d=new Date(); d.setHours(0,0,0,0); return d;};
const iso=d=>d.toISOString();
function fd(s,opt){ if(!s) return ''; const d=new Date(s.length===10?s+'T12:00:00':s); if(isNaN(d)) return ''; return d.toLocaleDateString('nb-NO',opt||{day:'numeric',month:'short',year:'numeric'}); }
function ago(s){ if(!s) return ''; const h=(Date.now()-new Date(s))/36e5; if(h<1) return 'nå nettopp'; if(h<24) return Math.round(h)+' t siden'; const d=Math.round(h/24); return d===1?'i går':d+' dager siden'; }
