/* ---------- I dag ---------- */
function kpis(){
  const Y='2027', ds=deals(), s=S.settings;
  const newRoom=d=>RM[d.room]?.nw;
  const sold=ds.filter(d=>d.stage==='bekreftet'&&(d.date||'').startsWith(Y)&&newRoom(d)).reduce((a,d)=>a+dval(d),0);
  const held=ds.filter(d=>d.stage==='holdt'&&(d.date||'').startsWith(Y)&&newRoom(d)).reduce((a,d)=>a+dval(d),0);
  const weighted=ds.filter(d=>OPEN.includes(d.stage)).reduce((a,d)=>a+dval(d)*ST[d.stage].p,0);
  const openCnt=ds.filter(d=>OPEN.includes(d.stage)).length;
  const former=orgs().filter(o=>o.former);
  const back=former.filter(o=>ds.some(d=>d.orgId===o.id&&d.stage!=='tapt'&&ST[d.stage].i>=1)).length;
  const ny=ds.filter(d=>d.stage==='ny'); const oldest=ny.reduce((m,d)=>Math.max(m,(Date.now()-new Date(d.createdAt||Date.now()))/36e5),0);
  return {sold,held,weighted,openCnt,former:former.length,back,ny:ny.length,oldest,base:s.costBase||1};
}
function weekFacts(){
  const wk=Date.now()-7*864e5, A=acts().filter(a=>new Date(a.at)>=wk), D=deals();
  const calls=A.filter(a=>['call','meeting','visning'].includes(a.type)).length;
  const newD=D.filter(d=>new Date(d.createdAt||0)>=wk).length;
  const won=D.filter(d=>d.stage==='bekreftet'&&new Date(d.stageAt||0)>=wk);
  const offers=D.filter(d=>d.stage==='tilbud'&&new Date(d.stageAt||0)>=wk).length;
  return [['Samtaler og møter',String(calls)],['Nye saker',String(newD)],['Tilbud sendt',String(offers)],['Bekreftet',won.length+' · '+short(won.reduce((a,d)=>a+dval(d),0))]];
}
async function makeReport(){
  if(!sample) return; UI.report.busy=true; UI.report.text=''; renderView(true);
  const k=kpis(), wf=weekFacts(), ds=deals().filter(d=>OPEN.includes(d.stage)||d.stage==='bekreftet').slice(0,40).map(d=>({org:orgName(d.orgId),sak:d.title,steg:ST[d.stage].n,sal:roomName(d.room),dato:d.date,verdi:dval(d)}));
  const prompt='Du skriver en kort ukerapport på norsk bokmål for utleie ved Litteraturhuset i Oslo, til daglig leder og utleieansvarlig. Maks 150 ord. Bruk 4-6 korte kulepunkter med tall, og avslutt med én linje om hva som prioriteres neste uke. Ingen overskrift, ingen hilsen, ingen tankestreker.\n\nNøkkeltall: solgt for 2027 i nye rom '+kr(k.sold)+' av nullpunkt '+kr(k.base)+'; holdt av '+kr(k.held)+'; vektet pipeline '+kr(k.weighted)+'; tidligere faste tilbake '+k.back+' av '+k.former+'; ubesvarte forespørsler '+k.ny+'.\nSiste sju dager: '+wf.map(x=>x[0]+': '+x[1]).join('; ')+'.\nSaker: '+JSON.stringify(ds);
  try{ await sample(prompt,{modelTier:'quick',onText:({text})=>{ UI.report.text=text; const o=$('#reportOut'); if(o) o.textContent=text; else renderView(true); }}); }
  catch(e){ UI.report.text=e.text||''; toast(sampleMsg(e)); if(['not_granted','sampling_disabled','not_declared','capability_disabled','capability_removed'].includes(e.code)) sample=null; }
  UI.report.busy=false; renderView(true);
}
function sampleMsg(e){ const c=e&&e.code; if(c==='cancelled') return 'Avbrutt.'; if(c==='rate_limited') return 'For mange forespørsler til Claude nå. Vent litt og prøv igjen.'; if(c==='not_granted'||c==='sampling_disabled') return 'Claude er ikke tilgjengelig her.'; if(c==='invalid_json') return 'Klarte ikke å lese svaret. Prøv igjen.'; if(c==='refused') return 'Claude ville ikke svare på dette.'; return 'Claude svarte ikke. Prøv igjen.'; }


