async function parseInquiry(){
  const I=UI.inbox; if(!I.text.trim()){ I.err='Lim inn teksten først.'; renderView(true); return; }
  I.busy=true; I.err=''; renderView(true);
  const rooms=ROOMS.map(r=>r.k+' ('+r.n+', '+r.cap+' pers.)').join('; ');
  const prompt='Les forespørselen om leie av lokaler hos Litteraturhuset i Oslo og svar KUN med ett JSON-objekt med disse feltene: {"org": string, "contact": string, "email": string, "phone": string, "title": kort navn på arrangementet, "date": "YYYY-MM-DD" eller "", "attendees": tall eller null, "room": en av romnøklene eller "", "pricing": "open" hvis åpent for publikum innen litteratur, politikk eller samfunn, ellers "closed", "needs": kort liste over ønsker som teknikk, strømming, servering, "summary": én til to setninger på norsk}. Tomme strenger når noe ikke står. Velg rom etter antall: '+rooms+'. Dagens dato er '+new Date().toISOString().slice(0,10)+'.\n\nForespørsel:\n'+I.text.slice(0,8000);
  try{ const r=await sample.json(prompt,{modelTier:'quick'}); const f=emptyInquiry();
    for(const k of Object.keys(f)) if(r&&r[k]!=null) f[k]=String(r[k]);
    if(!RM[f.room]) f.room=''; if(!/^\d{4}-\d{2}-\d{2}$/.test(f.date)) f.date=''; if(f.pricing!=='closed') f.pricing='open';
    I.f=f; I.ai=true; }
  catch(e){ I.err=sampleMsg(e); if(['not_granted','sampling_disabled','not_declared','capability_disabled','capability_removed'].includes(e.code)) sample=null; I.f=I.f||emptyInquiry(); }
  I.busy=false; renderView(true);
}
async function createFromInquiry(){
  const f=UI.inbox.f; if(!f.org.trim()){ toast('Skriv inn organisasjonen.'); return; }
  let org=findDuplicates(f.org.trim(),'')[0], orgId=org?.id;
  const contact=(f.contact||f.email||f.phone)?{name:f.contact,role:'',email:f.email,phone:f.phone}:null;
  if(!orgId){ orgId=uid('o'); await put('orgs',orgId,{name:f.org.trim(),segment:'',tier:'B',former:false,notes:'',website:'',contacts:contact?[contact]:[],createdAt:iso(new Date())}); }
  else if(contact&&!(org.contacts||[]).some(c=>c.email&&c.email===contact.email)){ const o=S.orgs[orgId]; await put('orgs',orgId,{...o,contacts:[...(o.contacts||[]),contact]}); }
  const id=uid('d'), r=RM[f.room], price=r?.price?(f.pricing==='open'?r.price[0]:r.price[1]):0;
  await put('deals',id,{facts:inqFacts(f,UI.inbox.ai,price,!!UI.inbox.text.trim()),orgId,title:f.title||'Forespørsel',stage:'ny',room:f.room,date:f.date,attendees:Number(f.attendees)||0,pricing:f.pricing,value:price,recurring:1,source:'inbound',ownerId:me.id||null,lostReason:'',notes:[f.needs,f.summary].filter(Boolean).join('\n'),createdAt:iso(new Date()),stageAt:iso(new Date())});
  if(f.summary||f.needs) await logAct({orgId,dealId:id,type:'note',text:'Forespørsel: '+[f.summary,f.needs].filter(Boolean).join(' Ønsker: ')});
  const due=new Date(); due.setDate(due.getDate()+(due.getDay()===5?3:due.getDay()===6?2:1)); due.setHours(12,0,0,0);
  await logAct({orgId,dealId:id,type:'task',text:'Svar på forespørselen fra '+f.org.trim(),due:iso(due)});
  UI.inbox={text:'',f:null,busy:false,err:''}; toast('Sak opprettet'); openDrawer('deal',id);
}

/* ---------- Tilbud ---------- */
function quoteCalc(Q){
  const r=RM[Q.room]||RM.collett, open=Q.ptype==='r';
  const base=r.k==='solstad'?Number(Q.solstadPrice)||0:(open?r.price[0]:r.price[1]);
  const reasons=[]; if(r.k==='wergeland') reasons.push('Wergeland'); if(Number(Q.stream)) reasons.push('strømming'); if(Q.wl) reasons.push('trådløse mikrofoner'); if(Number(Q.sound)===2) reasons.push('stor lydpakke');
  const tech=Q.tech||reasons.length>0; const techCost=tech?Math.max(3150,780*(Number(Q.techH)||0)):0;
  const L=[[r.n+(r.k==='solstad'?', pris etter tilbud':open?', rabattert':', ordinær'),base]];
  if(tech) L.push(['Tekniker'+(Number(Q.techH)?' '+Q.techH+' t':'')+(reasons.length?' (påkrevd: '+reasons.join(', ')+')':''),techCost]);
  if(Number(Q.sound)) L.push([(Number(Q.sound)===2?'Stor':'Liten')+' lydpakke', r.k==='wergeland'?(Number(Q.sound)===2?3200:1800):(Number(Q.sound)===2?1700:800)]);
  if(Q.wl) L.push(['Trådløst ekstrasett',1500]); if(Q.proj) L.push(['Projektor',650]);
  if(Number(Q.stream)) L.push(['Strømming',Number(Q.stream)]); if(Q.link) L.push(['Videolink',2500]); if(Q.host) L.push(['Arrangementsvert',1350]);
  const total=L.reduce((a,l)=>a+l[1],0);
  return {L,total,base,reasons,tech,room:r};
}
