/* ---------- composer (e-post) ---------- */
function firstEmail(orgId){ return ((S.orgs[orgId]?.contacts)||[]).map(c=>c.email).find(e=>/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(e||''))||''; }
const COMP={};
function composerHTML(p,text,subject){
  COMP[p]=COMP[p]||{}; if(COMP[p].subject==null) COMP[p].subject=subject||''; if(COMP[p].text==null||COMP[p].seed!==text){ COMP[p].text=text; COMP[p].seed=text; }
  return '<div class="grid" style="gap:10px; border-top:1px solid var(--rule); padding-top:12px">'+
   '<div class="form"><label class="f"><span>Til</span><input class="in" id="'+p+'To" type="email" value="'+esc(COMP[p].to||'')+'" placeholder="navn@organisasjon.no"></label><label class="f"><span>Emne</span><input class="in" id="'+p+'Sub" value="'+esc(COMP[p].subject)+'"></label></div>'+
   '<textarea class="in" id="'+p+'Body" rows="12">'+esc(COMP[p].text)+'</textarea>'+
   '<div class="row"><button class="btn sm" type="button" id="'+p+'Copy">Kopier tekst</button>'+(mcp?'<button class="btn sm" type="button" id="'+p+'Ol">Utkast i Outlook'+(INTEG['Microsoft 365']?.ok?'':' <small>(ikke verifisert)</small>')+'</button><button class="btn sm" type="button" id="'+p+'Gm">Utkast i Gmail'+(INTEG.Gmail?.ok?'':' <small>(ikke verifisert)</small>')+'</button>':'')+'<span class="note" id="'+p+'Msg"></span></div></div>';
}
function wireComposer(p,ctx){
  const to=$('#'+p+'To'); if(!to) return; const c=COMP[p], cx=ctx()||{};
  if(!c.to&&cx.to){ c.to=cx.to; to.value=cx.to; }
  to.addEventListener('input',()=>{ c.to=to.value; });
  $('#'+p+'Sub').addEventListener('input',e=>{ c.subject=e.target.value; });
  $('#'+p+'Body').addEventListener('input',e=>{ c.text=e.target.value; });
  $('#'+p+'Copy').addEventListener('click',()=>copyText(c.text,$('#'+p+'Body')));
  const msg=$('#'+p+'Msg');
  const send=async(server,tool,input,linkKey)=>{
    msg.textContent='Lager utkast …';
    try{ const r=await mcp.callTool(server,tool,input); const pl=r.payload||{}; const link=pl[linkKey];
      INTEG[server]={ok:true,at:new Date().toLocaleTimeString('nb-NO',{hour:'2-digit',minute:'2-digit'})}; msg.innerHTML='Utkast lagret i '+esc(server)+(link?' · <a href="'+esc(link)+'" target="_blank" rel="noopener">Åpne</a>':'');
      if(cx.orgId) logAct({orgId:cx.orgId,dealId:cx.dealId,type:'email',text:'E-postutkast laget: '+(c.subject||'uten emne')});
    }catch(e){ msg.textContent=mcpMsg(e,server); }
  };
  const valid=/^[^@\s]+@[^@\s]+\.[^@\s]+$/;
  $('#'+p+'Ol')?.addEventListener('click',()=>{ const html=c.text.split(/\n{2,}/).map(par=>'<p>'+esc(par).replace(/\n/g,'<br>')+'</p>').join(''); const inp={subject:c.subject.slice(0,255),body:html,bodyType:'html'}; if(valid.test(c.to||'')) inp.to=[c.to.trim()]; send('Microsoft 365','outlook_create_draft',inp,'webLink'); });
  $('#'+p+'Gm')?.addEventListener('click',()=>{ const inp={subject:c.subject,body:c.text}; if(valid.test(c.to||'')) inp.to=[c.to.trim()]; send('Gmail','create_draft',inp,'viewUrl'); });
}
function mcpMsg(e,server){ const c=e&&e.code;
  if(c==='server_not_connected'||c==='selection_required') return 'Legg til '+server+' under Innstillinger → Koblinger i claude.ai, og prøv igjen.';
  if(c==='needs_reauth') return 'Koble til '+server+' på nytt under Innstillinger → Koblinger i claude.ai.';
  if(c==='not_in_manifest') return server+' er ikke tillatt for denne siden. Du kan slå det på i sidens tillatelser.';
  if(c==='blocked_by_policy'||c==='approval_required') return 'Organisasjonen din tillater ikke dette fra verktøyet.';
  if(c==='tool_error') return server+' avviste utkastet: '+(e.message||'ukjent feil');
  if(c==='server_unavailable'||c==='upstream_error') return server+' svarte ikke. Sjekk utkastmappen før du prøver igjen.';
  return 'Kunne ikke lage utkast ('+(c||'ukjent')+').'; }
async function copyText(t,el){ try{ await navigator.clipboard.writeText(t); toast('Kopiert'); }catch(e){ if(el){ el.focus(); el.select(); toast('Merket. Trykk Ctrl+C eller Cmd+C for å kopiere.'); } } }

