const OLDROOMS=['wergeland','skram','berner','hagerup','kverneland','nedjma'];
function rng(seed){ let h=2166136261; for(const c of seed) h=Math.imul(h^c.charCodeAt(0),16777619); return ()=>{ h^=h<<13; h^=h>>>17; h^=h<<5; return ((h>>>0)%10000)/10000; }; }
let SYN=null;
function synthHistory(){
  const key=Object.keys(S.orgs).sort().join(); if(SYN&&SYN.key===key) return SYN.list;
  const Y=new Date().getFullYear(), M=new Date().getMonth()+1, out=[];
  for(const o of orgs()){ const r=rng(o.id), base=o.former?2+Math.floor(r()*5):Math.floor(r()*3), trend=(r()-.45)*.6, churn=r()<.15?Y-1-Math.floor(r()*2):null, start=Y-3-Math.floor(r()*3);
    for(let y=start;y<=Y;y++){ if(churn&&y>=churn) break; const n=Math.max(0,Math.round(base*(1+trend*(y-(Y-3)))+(r()-.5)*1.5));
      for(let i=0;i<n;i++){ const room=OLDROOMS[Math.floor(r()*OLDROOMS.length)], R=RM[room], open=r()<.7, extra=r()<.35?Math.round(r()*8)*500:0, m=1+Math.floor(r()*12), d=1+Math.floor(r()*27);
        if(y===Y&&m>M) continue;
        out.push({orgId:o.id,date:y+'-'+String(m).padStart(2,'0')+'-'+String(d).padStart(2,'0'),room,value:(open?R.price[0]:R.price[1])+extra,recurring:1}); } } }
  SYN={key,list:out}; return out;
}
function statData(){
  const Y=new Date().getFullYear(), T=UI.st, real=deals().filter(d=>d.stage==='bekreftet'&&d.date);
  const syn=T.syn==null?real.filter(d=>!d.example&&+d.date.slice(0,4)<Y).length<5:T.syn;
  const B=(syn?synthHistory().concat(real):real).map(d=>({org:d.orgId,y:+d.date.slice(0,4),md:d.date.slice(5),room:d.room,n:Number(d.recurring)||1,kr:dval(d),date:d.date})).filter(b=>b.y<=Y);
  return {B,syn,Y};
}
