function spark(vals,hi){ const mx=Math.max(1,...vals), w=84, h=22, st=vals.length>1?w/(vals.length-1):0;
  const pts=vals.map((v,i)=>(i*st).toFixed(1)+','+(h-2-(v/mx)*(h-4)).toFixed(1)).join(' ');
  return '<svg class="spark" viewBox="0 0 '+w+' '+h+'" aria-hidden="true"><polyline points="'+pts+'"/>'+(hi>=0?'<circle cx="'+(hi*st).toFixed(1)+'" cy="'+(h-2-(vals[hi]/mx)*(h-4)).toFixed(1)+'" r="2.4"/>':'')+'</svg>'; }
