UI.pmode='list'; UI.gen={seg:'',like:'',focus:'',n:6,busy:false,err:'',res:[],man:{name:'',website:'',segment:''}};
function syncProfiles(){
  for(const [id,d] of Object.entries(S.prospects||{})) if(d&&d.name) PROFILES[id]={...d,id,gen:true};
  for(const id of Object.keys(PROFILES)) if(PROFILES[id].gen&&!(S.prospects||{})[id]) delete PROFILES[id];
}
const slug=s=>String(s).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,40);
function knownNames(){ return [...new Set([...allOrgs().map(o=>o.name),...UI.gen.res.map(r=>r.name)])]; }
async function genProspects(){
  const G=UI.gen; if(!sample) return; G.busy=true; G.err=''; renderView(true);
  const like=G.like&&PROFILES[G.like]?PROFILES[G.like]:null, likeName=like?like.name:(G.like?orgName(G.like):'');
  const prompt='Du hjelper markedskonsulenten på Litteraturhuset i Oslo med å finne nye kunder til utleie av salene fra 2027: Solstad (opptil 320), Collett (24 til 120), Hofmo (16 til 90), Berner-salongen (10 til 30) og to møterom. Åpne arrangementer innen litteratur, politikk og samfunn får rabatt.\n'+
   'Foreslå '+G.n+' konkrete, virkelige organisasjoner i Norge, helst i Oslo, som jevnlig holder seminarer, lanseringer, debatter, fagdager eller konferanser.'+(G.seg?' Segment: '+G.seg+'.':'')+(likeName?' De skal ligne på '+likeName+(like?' ('+like.about+')':'')+'.':'')+(G.focus?' Fokus: '+G.focus+'.':'')+
   '\nIkke ta med noen av disse: '+knownNames().join('; ')+'.\nBare organisasjoner du er sikker på finnes. Ikke finn på telefonnumre, e-postadresser eller datoer. Ingen tankestreker. Norsk bokmål.\n'+
   'Svar KUN med JSON: {"prospects":[{"name":string,"website":string (hovedside, tom hvis usikker),"segment": en av '+JSON.stringify(SEGMENTS)+',"size":"S"|"M"|"L","about":"1-2 setninger om hvem de er","events":["2-3 typer arrangementer de holder"],"angle":"1-2 setninger om hvorfor Litteraturhuset passer og hvilket rom","opener":"åpningsreplikk på telefon, starter med «Hei, jeg ringer fra Litteraturhuset»","askFor":"hvilken rolle man bør be om"}]}';
  try{ const r=await sample.json(prompt,{modelTier:'quick'}); const known=new Set(knownNames().map(n=>n.toLowerCase()));
    const list=(r&&Array.isArray(r.prospects)?r.prospects:[]).filter(x=>x&&x.name&&!known.has(String(x.name).toLowerCase()));
    G.res=G.res.concat(list.map(x=>({id:'g-'+slug(x.name),name:String(x.name),website:String(x.website||''),segment:SEGMENTS.includes(x.segment)?x.segment:'',size:['S','M','L'].includes(x.size)?x.size:'M',about:String(x.about||''),events:(x.events||[]).map(String).slice(0,4),angle:String(x.angle||''),opener:String(x.opener||''),contact:{askFor:String(x.askFor||'')},lhHistory:'',bestMonths:[],sources:x.website?[String(x.website)]:[],tier:'B'})));
    if(!list.length) G.err='Fant ingen nye forslag. Prøv et annet segment eller fokus.';
  }catch(e){ G.err=sampleMsg(e); }
  G.busy=false; renderView(true);
}
