/* forbruk per år i kundekortet */
function yearChart(id){
  const {B,Y}=statData(), mine=B.filter(b=>b.org===id); if(!mine.length) return '';
  const y0=Math.min(Y-4,...mine.map(b=>b.y)), ys=[]; for(let y=y0;y<=Y;y++) ys.push({y,kr:0,n:0});
  for(const b of mine){ const r=ys[b.y-y0]; if(r){ r.kr+=b.kr; r.n+=b.n; } }
  const mx=Math.max(1,...ys.map(r=>r.kr));
  return '<section class="kc-sec" style="--c:var(--teal)"><h3>Forbruk per år</h3><div class="kc-bars">'+ys.map(r=>'<div class="kc-bar'+(r.y===Y?' now':'')+'" title="'+r.y+': '+esc(kr(r.kr))+', '+r.n+' bookinger"><b>'+(r.kr?short(r.kr):'')+'</b><i style="height:'+(r.kr/mx*100)+'%"></i><span>'+r.y+(r.y===Y?'*':'')+'</span><small>'+(r.n?r.n+' stk':'')+'</small></div>').join('')+'</div><p class="note">* hittil i år.</p></section>';
}
/* ---------- lagrestatus ---------- */
function syncState(){
  const n=SYNC.queue.size, t=SYNC.lastSaved?SYNC.lastSaved.toLocaleTimeString('nb-NO',{hour:'2-digit',minute:'2-digit'}):'';
  if(!db) return {k:'demo',t:'Demo · endringer lagres ikke'};
  if(!navigator.onLine) return {k:'offline',t:n?'Frakoblet · '+n+' '+(n===1?'endring venter':'endringer venter')+' på synkronisering':'Frakoblet'};
  if(n&&SYNC.err&&!SYNC.inflight.size) return {k:'error',t:'Kunne ikke lagre · endringene dine er beholdt'};
  if(SYNC.inflight.size) return {k:'saving',t:n>1?'Synkroniserer '+n+' endringer …':'Lagrer …'};
  if(n) return {k:'saving',t:'Venter på lagring …'};
  if(readOnly) return {k:'ro',t:'Lesetilgang · du kan ikke endre'};
  return {k:'ok',t:t?'Alle endringer lagret · '+t:'Tilkoblet · ingen ulagrede endringer'};
}
function syncUI(){
  const m=$('#mode'); if(!m) return; const s=syncState();
  m.className='sync '+s.k; m.setAttribute('role','status');
  m.innerHTML='<button type="button" class="sync-b" id="syncBtn" aria-expanded="'+!!UI.syncOpen+'"><i aria-hidden="true"></i><span>'+esc(s.t)+'</span></button>'+
   (UI.syncOpen?'<div class="sync-p"><p>'+({demo:'Dette er en demo uten database. Ingenting du endrer blir lagret.',ok:'Alle endringer er bekreftet lagret i den delte databasen.',saving:'Endringene sendes nå. De er ikke lagret før databasen bekrefter.',offline:'Du er frakoblet. Endringene ligger trygt i denne nettleseren og sendes når du er på nett igjen.',error:'Databasen avviste eller svarte ikke. Endringene er beholdt i denne nettleseren.',ro:'Du har lesetilgang. Be eieren om skrivetilgang.'})[s.k]+'</p>'+
    (SYNC.queue.size?'<ul>'+[...SYNC.queue.values()].slice(0,6).map(e=>'<li>'+esc(({orgs:'Kontakt',deals:'Sak',acts:'Aktivitet',audit:'Logg',offers:'Tilbud',prospects:'Prospekt',settings:'Innstillinger',imports:'Import'})[e.col]||e.col)+' · '+esc(e.doc?.name||e.doc?.title||e.doc?.text||e.id).slice(0,40)+'</li>').join('')+'</ul><div class="row"><button class="btn sm" type="button" id="syncRetry">Prøv igjen</button><button class="btn ghost sm danger" type="button" id="syncDrop">Forkast ventende</button></div>':'')+'</div>':'');
  $('#syncBtn').onclick=()=>{ UI.syncOpen=!UI.syncOpen; syncUI(); };
  const r=$('#syncRetry'); if(r) r.onclick=()=>{ SYNC.err=null; flush(); };
  const d=$('#syncDrop'); if(d) d.onclick=()=>{ if(UI.syncDropAsk){ UI.syncDropAsk=false; discardQueue(); } else { UI.syncDropAsk=true; d.textContent='Klikk igjen for å forkaste '+SYNC.queue.size; } };
}
function setMode(){ syncUI(); }

/* ---------- duplikater og sammenslåing ---------- */
const STOP=/\b(stiftelsen|stiftelse|foreningen|forening|as|asa|sa|the|og|i|norge|norsk|norske|oslo)\b/g;
function normName(n){ return String(n||'').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/\(.*?\)/g,' ').replace(/[·.,&\-/]/g,' ').replace(STOP,' ').replace(/\s+/g,' ').trim(); }
function domainOf(w){ const m=String(w||'').toLowerCase().replace(/^https?:\/\//,'').replace(/^www\./,'').split(/[/?#]/)[0]; return m.includes('.')?m:''; }
function isDup(a,b){ const na=normName(a.name), nb=normName(b.name); if(!na||!nb) return false; if(na===nb) return true; if(na.length>=6&&nb.length>=6&&(na.startsWith(nb+' ')||nb.startsWith(na+' '))) return true; const da=domainOf(a.website), dbb=domainOf(b.website); return !!(da&&da===dbb); }
function findDuplicates(name,website,exceptId){ const probe={name,website}; return orgs().filter(o=>o.id!==exceptId&&isDup(probe,o)); }
function dupPairs(){ const L=orgs(), out=[]; for(let i=0;i<L.length;i++) for(let j=i+1;j<L.length;j++) if(isDup(L[i],L[j])&&!(S.settings.notDup||[]).includes(L[i].id+'|'+L[j].id)) out.push([L[i],L[j]]); return out; }
async function mergeOrgs(keepId,dropId){
  const k=S.orgs[keepId], d=S.orgs[dropId]; if(!k||!d) return;
  const contacts=[...(k.contacts||[])]; for(const c of d.contacts||[]) if(!contacts.some(x=>(x.email&&x.email===c.email)||(x.name&&x.name===c.name))) contacts.push(c);
  const merged={...k,contacts,former:!!(k.former||d.former),website:k.website||d.website,segment:k.segment||d.segment,notes:[k.notes,d.notes].filter(Boolean).join('\n\n')};
  await put('orgs',keepId,merged,{action:'slått sammen med «'+d.name+'»'});
  for(const x of deals().filter(x=>x.orgId===dropId)) await put('deals',x.id,{...S.deals[x.id],orgId:keepId},{action:'flyttet ved sammenslåing'});
  for(const a of acts().filter(a=>a.orgId===dropId)) await put('acts',a.id,{...S.acts[a.id],orgId:keepId});
  await put('orgs',dropId,{...d,deletedAt:iso(new Date()),deletedBy:me.name||'',deleteBatch:uid('del'),mergedInto:keepId},{action:'slått sammen inn i «'+k.name+'»'});
  toast('«'+d.name+'» er slått sammen med «'+k.name+'»');
}

/* ---------- konflikter, ulagrede endringer og fokus i skuffen ---------- */
const EDIT={org:['name','segment','tier','website','notes','former','contacts'],deal:['orgId','title','room','date','time','attendees','setup','techNeeds','catering','pricing','value','recurring','source','notes','lostReason']};
const FNAME={time:'Tidspunkt',setup:'Romoppsett',techNeeds:'Teknikk og strømming',catering:'Servering',facts:'Avklaringer',ownerId:'Ansvarlig',ownerName:'Ansvarlig (navn)',name:'Navn',segment:'Segment',tier:'Prioritet',website:'Nettside',notes:'Notater',former:'Fast leietaker',contacts:'Kontaktpersoner',orgId:'Organisasjon',title:'Arrangement',room:'Rom',date:'Dato',attendees:'Antall',pricing:'Type',value:'Verdi',recurring:'Antall ganger',source:'Kilde',lostReason:'Tapt fordi',stage:'Steg'};
const same=(a,b)=>JSON.stringify(a??'')===JSON.stringify(b??'');
function isDirty(D){ if(!D||!D.draft) return false; const F=EDIT[D.kind]; if(!D.id) return D.kind==='deal'?!!(D.draft.title||D.draft.orgId):!!D.draft.name; return F.some(f=>!same(D.draft[f],D.base?.[f])); }
function fmtVal(f,v){ if(f==='contacts') return (v||[]).map(c=>c.name||c.email).filter(Boolean).join(', ')||'Ingen'; if(f==='orgId') return orgName(v); if(f==='room') return roomName(v); if(typeof v==='boolean') return v?'Ja':'Nei'; return v===''||v==null?'Tom':String(v); }
async function saveChecked(col,D,doc){
  const cur=S[col][D.id];
  if(D.id&&cur&&D.baseRev!=null&&(cur.rev||0)!==D.baseRev&&!D.force){ D.conflict=true; renderDrawer(true); return null; }
  D.force=false; D.conflict=false; return put(col,D.id,doc);
}
function drawerNotice(D){ const ss=syncState(); return (ss.k==='error'?'<div class="notice err" role="alert"><b>Kunne ikke lagre · endringene dine er beholdt.</b><div class="row"><button class="btn sm" type="button" data-cf="retry">Prøv igjen</button></div></div>':ss.k==='offline'&&SYNC.queue.size?'<div class="notice warn" role="status"><b>'+esc(ss.t)+'.</b> Du kan fortsette å jobbe.</div>':'')+drawerNotice2(D); }
function drawerNotice2(D){
  if(!D.id) return ''; const col=D.kind==='deal'?'deals':'orgs', cur=S[col][D.id]; if(!cur) return '';
  const who=cur.updatedByName||'En kollega', when=cur.updatedAt?new Date(cur.updatedAt).toLocaleTimeString('nb-NO',{hour:'2-digit',minute:'2-digit'}):'';
  if(D.conflict){ const F=EDIT[D.kind], rows=F.filter(f=>!same(cur[f],D.base?.[f])||!same(D.draft[f],D.base?.[f])).filter(f=>!same(cur[f],D.draft[f]));
    return '<div class="notice err" role="alert"><b>'+esc(who)+' oppdaterte dette kortet kl. '+esc(when)+' mens du redigerte.</b><p>Se forskjellene før du lagrer. Ingenting er overskrevet ennå.</p>'+
     '<table class="cmp"><thead><tr><th>Felt</th><th>Din versjon</th><th>Deres versjon</th></tr></thead><tbody>'+rows.map(f=>'<tr><td>'+esc(FNAME[f]||f)+'</td><td>'+esc(fmtVal(f,D.draft[f]))+'</td><td>'+esc(fmtVal(f,cur[f]))+'</td></tr>').join('')+'</tbody></table>'+
     '<div class="row"><button class="btn primary sm" type="button" data-cf="merge">Slå sammen</button><button class="btn sm" type="button" data-cf="theirs">Bruk deres</button><button class="btn ghost sm danger" type="button" data-cf="mine">Overskriv med min</button></div><p class="note">Slå sammen beholder dine endrede felt og tar resten fra deres versjon.</p></div>'; }
  if(D.baseRev!=null&&(cur.rev||0)!==D.baseRev) return '<div class="notice info" role="status"><b>'+esc(who)+' oppdaterte kortet kl. '+esc(when)+'.</b> '+(isDirty(D)?'Du har egne ulagrede endringer. Du får se forskjellene når du lagrer.':'')+' <button class="btn ghost sm" type="button" data-cf="reload">Vis nyeste versjon</button></div>';
  if(D.closing) return '<div class="notice warn" role="alert"><b>Du har ulagrede endringer.</b><div class="row"><button class="btn primary sm" type="button" data-cf="save">Lagre og lukk</button><button class="btn ghost sm danger" type="button" data-cf="discard">Forkast endringene</button><button class="btn ghost sm" type="button" data-cf="stay">Fortsett å redigere</button></div></div>';
  return '';
}
function wireNotice(root,D){
  root.querySelectorAll('[data-cf]').forEach(b=>b.addEventListener('click',()=>{ const a=b.dataset.cf, col=D.kind==='deal'?'deals':'orgs', cur=S[col][D.id];
    if(a==='theirs'||a==='reload'){ D.draft=JSON.parse(JSON.stringify(cur)); D.base=JSON.parse(JSON.stringify(cur)); D.baseRev=cur.rev||0; D.conflict=false; renderDrawer(true); }
    else if(a==='mine'){ D.force=true; D.conflict=false; root.querySelector(D.kind==='deal'?'#dSave':'#oSave')?.click(); }
    else if(a==='merge'){ const next={...cur}; for(const f of EDIT[D.kind]) if(!same(D.draft[f],D.base?.[f])) next[f]=D.draft[f]; D.draft=next; D.base=JSON.parse(JSON.stringify(cur)); D.baseRev=cur.rev||0; D.conflict=false; if(D.kind==='org') D.tab='detaljer'; renderDrawer(true); root.querySelector(D.kind==='deal'?'#dSave':'#oSave')?.click(); }
    else if(a==='save'){ D.closing=false; D.closeAfter=true; if(D.kind==='org') D.tab='detaljer'; renderDrawer(true); $('#drawer-root').querySelector(D.kind==='deal'?'#dSave':'#oSave')?.click(); }
    else if(a==='discard'){ closeDrawer(true); }
    else if(a==='retry'){ SYNC.err=null; flush().then(()=>renderDrawer(true)); }
    else if(a==='stay'){ D.closing=false; renderDrawer(true); } }));
}
function trapFocus(e){ const d=$('#drawer-root .drawer'); if(!d||e.key!=='Tab') return; const f=[...d.querySelectorAll('button,[href],input,select,textarea,[tabindex]:not([tabindex="-1"])')].filter(x=>!x.disabled&&x.offsetParent); if(!f.length) return; const a=f[0], z=f[f.length-1]; if(e.shiftKey&&document.activeElement===a){ e.preventDefault(); z.focus(); } else if(!e.shiftKey&&document.activeElement===z){ e.preventDefault(); a.focus(); } }
document.addEventListener('keydown',trapFocus);

/* ---------- import: last opp, forhåndsvis, koble, valider, duplikater, prøvekjøring, logg ---------- */
UI.imp={step:1,type:'orgs',rows:null,head:null,name:'',map:{},act:{},result:null};
const IMPF={orgs:[['name','Organisasjon',true],['segment','Segment'],['contact','Kontaktperson'],['email','E-post'],['phone','Telefon']],deals:[['org','Arrangør',true],['title','Arrangement'],['date','Dato',true],['room','Sal'],['status','Status'],['attendees','Antall'],['value','Beløp']]};
function impAnalyze(){
  const I=UI.imp, m=I.map, g=(r,k)=>m[k]!=null&&m[k]!==''?String(r[m[k]]??'').trim():'', seen={}, out=[];
  I.rows.slice(0,500).forEach((r,i)=>{ const errs=[]; let key, dup=null;
    if(I.type==='orgs'){ const name=g(r,'name'); if(!name) errs.push('Mangler navn'); const em=g(r,'email'); if(em&&!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(em)) errs.push('Ugyldig e-post'); key=normName(name); if(name) dup=findDuplicates(name,'')[0]||null; out.push({i,r,name,errs,dup,inFile:key&&seen[key]!=null?seen[key]:null}); if(key&&seen[key]==null) seen[key]=i; }
    else { const org=g(r,'org'), dt=toISODate(g(r,'date')); if(!org) errs.push('Mangler arrangør'); if(!dt) errs.push('Ukjent datoformat'); const v=g(r,'value'); if(v&&isNaN(Number(v.replace(/[^\d,.-]/g,'').replace(',','.')))) errs.push('Beløp er ikke et tall'); dup=org?findDuplicates(org,'')[0]||null:null; key=normName(org)+'|'+dt+'|'+roomKey(g(r,'room')); const exists=dt&&dup&&deals().some(d=>d.orgId===dup.id&&d.date===dt); out.push({i,r,name:org,date:dt,errs,dup,exists,inFile:seen[key]!=null?seen[key]:null}); if(seen[key]==null) seen[key]=i; }
  });
  for(const x of out) if(I.act[x.i]==null) I.act[x.i]=x.errs.length?'skip':x.inFile!=null||x.exists?'skip':(I.type==='orgs'&&x.dup)?'update':'create';
  return out;
}
async function runImport(){
  const I=UI.imp, A=impAnalyze(), m=I.map, g=(r,k)=>m[k]!=null&&m[k]!==''?String(r[m[k]]??'').trim():'', impId=uid('imp'), log={created:[],updated:[]};
  const newOrgs={};
  const ensure=async(name,extra)=>{ const d=findDuplicates(name,'')[0]; if(d) return d.id; const k=normName(name); if(newOrgs[k]) return newOrgs[k]; const id=uid('o'); newOrgs[k]=id; await put('orgs',id,{name,segment:extra?.segment||'',tier:'B',former:!!extra?.former,notes:'Importert fra '+I.name,website:'',contacts:extra?.contact?[extra.contact]:[],importId:impId},{action:'importert'}); log.created.push(['orgs',id]); return id; };
  for(const x of A){ const act=I.act[x.i]; if(act==='skip'||x.errs.length) continue; const r=x.r;
    if(I.type==='orgs'){ const c=(g(r,'contact')||g(r,'email')||g(r,'phone'))?{name:g(r,'contact'),role:'',email:g(r,'email'),phone:g(r,'phone')}:null, seg=SEGMENTS.includes(g(r,'segment'))?g(r,'segment'):'';
      if(act==='update'&&x.dup){ const o=S.orgs[x.dup.id]; log.updated.push(['orgs',x.dup.id,JSON.parse(JSON.stringify(o))]); await put('orgs',x.dup.id,{...o,segment:o.segment||seg,contacts:c&&!(o.contacts||[]).some(k=>k.email&&k.email===c.email)?[...(o.contacts||[]),c]:(o.contacts||[])},{action:'oppdatert ved import'}); }
      else { const id=uid('o'); await put('orgs',id,{name:x.name,segment:seg,tier:'B',former:false,notes:'Importert fra '+I.name,website:'',contacts:c?[c]:[],importId:impId},{action:'importert'}); log.created.push(['orgs',id]); } }
    else { const orgId=await ensure(x.name,{former:true}); const stt=g(r,'status').toLowerCase(); const stage=/avl|kansel|tapt/.test(stt)?'tapt':/hold|reserv|forel/.test(stt)?'holdt':/tilbud/.test(stt)?'tilbud':'bekreftet'; const id=uid('d');
      await put('deals',id,{orgId,title:g(r,'title')||'Booking',stage,room:roomKey(g(r,'room')),date:x.date,attendees:Number(g(r,'attendees').replace(/\D/g,''))||0,pricing:'open',value:Number(g(r,'value').replace(/[^\d,.-]/g,'').replace(',','.'))||0,recurring:1,source:'import',ownerId:null,lostReason:'',notes:'Importert fra '+I.name,stageAt:iso(new Date()),importId:impId},{action:'importert'}); log.created.push(['deals',id]); } }
  const rec={file:I.name,type:I.type,at:iso(new Date()),by:me.name||'',created:log.created,updated:log.updated,rolledBack:false};
  S.imports[impId]=rec; await commit('imports',impId,rec,'set');
  I.result={id:impId,created:log.created.length,updated:log.updated.length,skipped:A.filter(x=>I.act[x.i]==='skip'||x.errs.length).length}; I.step=5; renderView(true);
}
async function rollbackImport(id){ const rec=S.imports[id]; if(!rec||rec.rolledBack) return; const b=uid('del');
  for(const [col,did] of rec.created) if(S[col][did]) await put(col,did,{...S[col][did],deletedAt:iso(new Date()),deletedBy:me.name||'',deleteBatch:b},{action:'import angret'});
  for(const [col,did,prev] of rec.updated) if(prev) await put(col,did,prev,{action:'import angret'});
  rec.rolledBack=true; rec.rolledBackAt=iso(new Date()); await commit('imports',id,rec,'set'); toast('Importen er angret. Opprettede oppføringer ligger i papirkurven.'); renderView(true); }
function importHTML(){
  const I=UI.imp, F=IMPF[I.type], steps=['Last opp','Koble kolonner','Valider','Prøvekjøring','Resultat'];
  let body='';
  if(I.step===1) body='<div class="row"><div class="seg" role="group" aria-label="Type import"><button type="button" data-imp="orgs" aria-pressed="'+(I.type==='orgs')+'">Kontakter</button><button type="button" data-imp="deals" aria-pressed="'+(I.type==='deals')+'">Bookinger</button></div><label class="btn"><input type="file" id="impFile" accept=".csv,text/csv,text/plain" class="sr">Velg CSV-fil</label></div><p class="note">'+(I.type==='orgs'?'Kontakter: organisasjon, segment, kontaktperson, e-post, telefon.':'Bookinger fra bookingsystemet: arrangør, arrangement, dato, sal, status, antall, beløp. Blir saker med historikk.')+' Ingenting lagres før du har sett en prøvekjøring.</p>';
  else if(I.step===2) body='<p class="note">'+esc(I.name)+' · '+I.rows.length+' rader. Sjekk at hver kolonne er koblet riktig.</p><div class="form">'+F.map(([k,n,req])=>'<label class="f"><span>'+n+(req?' *':'')+'</span><select class="in" data-map="'+k+'"><option value="">Ikke i filen</option>'+I.head.map((h,i)=>'<option value="'+i+'"'+(String(I.map[k])===String(i)?' selected':'')+'>'+esc(h)+'</option>').join('')+'</select></label>').join('')+'</div>'+
   '<div class="tbl"><table class="dense"><thead><tr>'+F.map(([,n])=>'<th>'+n+'</th>').join('')+'</tr></thead><tbody>'+I.rows.slice(0,4).map(r=>'<tr>'+F.map(([k])=>'<td>'+esc(I.map[k]!==''&&I.map[k]!=null?r[I.map[k]]:'')+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>'+
   '<div class="row"><button class="btn primary" type="button" data-istep="3"'+(F.filter(f=>f[2]).every(([k])=>I.map[k]!==''&&I.map[k]!=null)?'':' disabled aria-describedby="mapReq"')+'>Valider</button><button class="btn ghost" type="button" data-istep="1">Tilbake</button><span class="note" id="mapReq">Felt med * må kobles.</span></div>';
  else if(I.step===3||I.step===4){ const A=impAnalyze(), cnt={create:0,update:0,skip:0}; A.forEach(x=>cnt[x.errs.length?'skip':I.act[x.i]]++); const err=A.filter(x=>x.errs.length).length, dups=A.filter(x=>x.dup||x.inFile!=null||x.exists).length;
    if(I.step===3) body='<div class="strip"><span><b>'+A.length+'</b> rader</span><span><b>'+err+'</b> med feil</span><span><b>'+dups+'</b> mulige duplikater</span></div><div class="tbl sticky"><table class="dense"><thead><tr><th>#</th><th>'+(I.type==='orgs'?'Organisasjon':'Arrangør')+'</th>'+(I.type==='deals'?'<th>Dato</th>':'')+'<th>Kontroll</th><th>Handling</th></tr></thead><tbody>'+A.map(x=>'<tr'+(x.errs.length?' class="bad"':'')+'><td class="n">'+(x.i+1)+'</td><td>'+esc(x.name||'')+'</td>'+(I.type==='deals'?'<td>'+esc(x.date||'')+'</td>':'')+'<td>'+(x.errs.length?'<span class="st-err">'+esc(x.errs.join(', '))+'</span>':x.inFile!=null?'<span class="st-warn">Duplikat av rad '+(x.inFile+1)+'</span>':x.exists?'<span class="st-warn">Bookingen finnes allerede</span>':x.dup?'<span class="st-warn">Ligner på «'+esc(x.dup.name)+'»</span>':'<span class="st-ok">OK</span>')+'</td><td>'+(x.errs.length?'Hoppes over':'<select class="in fsel" data-iact="'+x.i+'" aria-label="Handling for rad '+(x.i+1)+'">'+(I.type==='orgs'&&x.dup?'<option value="update"'+(I.act[x.i]==='update'?' selected':'')+'>Oppdater «'+esc(x.dup.name)+'»</option>':'')+'<option value="create"'+(I.act[x.i]==='create'?' selected':'')+'>'+(I.type==='orgs'?'Opprett ny':'Importer')+'</option><option value="skip"'+(I.act[x.i]==='skip'?' selected':'')+'>Hopp over</option></select>')+'</td></tr>').join('')+'</tbody></table></div><div class="row"><button class="btn primary" type="button" data-istep="4">Prøvekjøring</button><button class="btn ghost" type="button" data-istep="2">Tilbake</button></div>';
    else body='<div class="notice info"><b>Prøvekjøring. Ingenting er lagret ennå.</b><p>'+(I.type==='orgs'?cnt.create+' nye kontakter, '+cnt.update+' eksisterende oppdateres':cnt.create+' bookinger importeres som saker. Arrangører som ikke finnes, opprettes')+', '+cnt.skip+' rader hoppes over. Importen kan angres i importloggen.</p></div><div class="row"><button class="btn primary" type="button" id="impGo"'+(cnt.create+cnt.update?'':' disabled')+'>Importer '+(cnt.create+cnt.update)+' rader</button><button class="btn ghost" type="button" data-istep="3">Tilbake</button>'+(cnt.create+cnt.update?'':'<span class="note">Ingen rader å importere.</span>')+'</div>'; }
  else { const R=I.result; body='<div class="notice ok"><b>Importen er fullført.</b><p>'+R.created+' opprettet, '+R.updated+' oppdatert, '+R.skipped+' hoppet over. Alt er merket med importnummeret og kan angres.</p></div><div class="row"><button class="btn" type="button" id="impNew">Ny import</button><button class="btn ghost danger" type="button" data-roll="'+R.id+'">Angre denne importen</button></div>'; }
  return '<ol class="steps">'+steps.map((s,i)=>'<li'+(I.step===i+1?' aria-current="step"':I.step>i+1?' class="done"':'')+'>'+s+'</li>').join('')+'</ol>'+body;
}
function wireImport(v){
  const I=UI.imp;
  v.querySelectorAll('[data-imp]').forEach(b=>b.addEventListener('click',()=>{ UI.imp={step:1,type:b.dataset.imp,rows:null,head:null,name:'',map:{},act:{},result:null}; renderView(true); }));
  $('#impFile')?.addEventListener('change',e=>{ const f=e.target.files[0]; if(!f) return; const r=new FileReader(); r.onload=()=>{ const rows=parseCSV(String(r.result)); if(rows.length<2){ toast('Fant ingen rader i filen.'); return; } I.head=rows[0]; I.rows=rows.slice(1); I.name=f.name; I.map=detect(I.head,I.type); I.act={}; I.step=2; renderView(true); }; r.readAsText(f); });
  v.querySelectorAll('[data-map]').forEach(s=>s.addEventListener('change',()=>{ I.map[s.dataset.map]=s.value; I.act={}; renderView(true); }));
  v.querySelectorAll('[data-istep]').forEach(b=>b.addEventListener('click',()=>{ I.step=Number(b.dataset.istep); renderView(true); }));
  v.querySelectorAll('[data-iact]').forEach(s=>s.addEventListener('change',()=>{ I.act[s.dataset.iact]=s.value; }));
  $('#impGo')?.addEventListener('click',e=>{ e.currentTarget.disabled=true; e.currentTarget.textContent='Importerer …'; runImport(); });
  $('#impNew')?.addEventListener('click',()=>{ UI.imp={step:1,type:I.type,rows:null,head:null,name:'',map:{},act:{},result:null}; renderView(true); });
}

