function integ(k){ // ekte tilstand, aldri antatt
  if(k==='db') return !db?['proto','Kun prototype','Demo uten database. Ingenting lagres.']:readOnly?['auth','Lesetilgang','Du kan lese, men ikke endre.']:['ok','Tilkoblet','Delt artefakt-database. Prototype, ikke produksjonsdatabase.'];
  if(k==='claude') return !sample?['off','Utilgjengelig','Ikke tillatt på denne siden.']:INTEG.claude?.ok?['ok','Tilkoblet','Testet kl. '+INTEG.claude.at]:INTEG.claude?.err?['off','Feilet','Siste test: '+INTEG.claude.err]:['cfg','Ikke testet','Tillatt på siden. Trykk Test for å sjekke.'];
  if(k==='outlook'||k==='gmail'){ const s=k==='outlook'?'Microsoft 365':'Gmail'; return !mcp?['off','Utilgjengelig','Koblingen er ikke tillatt på siden.']:INTEG[s]?.ok?['ok','Tilkoblet','Utkast laget kl. '+INTEG[s].at]:['auth','Autentisering kreves','Ikke verifisert. Krever at '+s+' er koblet til i claude.ai. Bekreftes første gang et utkast lages.']; }
  if(k==='booking') return ['cfg','Konfigurasjon kreves','Ingen direkte kobling. Bruk CSV-import til API-et er avklart.'];
}
