  $('#expAll')?.addEventListener('click',async()=>{ const data={exportedAt:iso(new Date()),by:me.name||'',orgs:S.orgs,deals:S.deals,acts:S.acts,offers:S.offers,prospects:S.prospects,audit:S.audit,imports:S.imports,settings:S.settings}; try{ await dl.save({filename:'salong-backup-'+new Date().toISOString().slice(0,10)+'.json',data:JSON.stringify(data,null,1)}); }catch(e){ if(e.code!=='declined') toast('Nedlastingen ble ikke fullført.'); } });
  $('#expDeals')?.addEventListener('click',()=>exportCSV('deals'));
  $('#expOrgs')?.addEventListener('click',()=>exportCSV('orgs'));
